--
-- Name: reviews; Type: TABLE; Schema: drivers; Owner: -
--

CREATE TABLE drivers.reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    driverid uuid NOT NULL,
    passengerid uuid NOT NULL,
    tripid uuid NOT NULL,
    rating smallint NOT NULL,
    comment character varying(500),
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    CONSTRAINT ck_rev_rating CHECK (((rating >= 1) AND (rating <= 5)))
);


--
-- Name: trippaths; Type: TABLE; Schema: drivers; Owner: -
--

CREATE TABLE drivers.trippaths (
    tripid uuid NOT NULL,
    driverid uuid NOT NULL,
    pointcount integer NOT NULL,
    distancekm double precision DEFAULT 0 NOT NULL,
    startedat timestamp without time zone NOT NULL,
    endedat timestamp without time zone NOT NULL,
    points text NOT NULL,
    details jsonb,
    consolidatedat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL
);


--
-- Name: TABLE trippaths; Type: COMMENT; Schema: drivers; Owner: -
--

COMMENT ON TABLE drivers.trippaths IS 'Recorrido GPS consolidado por viaje. Se lee aqui el detalle de viajes pasados; el crudo (locationhistory) se archiva en Parquet.';


--
-- Name: COLUMN trippaths.points; Type: COMMENT; Schema: drivers; Owner: -
--

COMMENT ON COLUMN drivers.trippaths.points IS 'Polilinea codificada (Google encoded polyline, factor 1e6). Ver drivers.encode_polyline.';


--
-- Name: COLUMN trippaths.details; Type: COMMENT; Schema: drivers; Owner: -
--

COMMENT ON COLUMN drivers.trippaths.details IS 'jsonb {"t":[ms desde startedat por punto], "s":[speedkmh], "h":[heading]} en el mismo orden que points.';


--
-- Name: vehiclephotos; Type: TABLE; Schema: drivers; Owner: -
--

CREATE TABLE drivers.vehiclephotos (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    vehicleid uuid NOT NULL,
    phototype character varying(10) NOT NULL,
    url character varying(500) NOT NULL,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updatedat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    CONSTRAINT ck_vehiclephotos_type CHECK (((phototype)::text = ANY ((ARRAY['front'::character varying, 'side'::character varying, 'plate'::character varying])::text[])))
);


--
-- Name: vehicles; Type: TABLE; Schema: drivers; Owner: -
--

CREATE TABLE drivers.vehicles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    driverid uuid NOT NULL,
    plate character varying(20) NOT NULL,
    brand character varying(60) NOT NULL,
    model character varying(60) NOT NULL,
    year smallint NOT NULL,
    color character varying(30) NOT NULL,
    isactive boolean DEFAULT true NOT NULL,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    photourl character varying(500)
);


--
-- Name: complaintcounters; Type: TABLE; Schema: landing; Owner: -
--

CREATE TABLE landing.complaintcounters (
    year integer NOT NULL,
    last integer NOT NULL
);


--
-- Name: complaints; Type: TABLE; Schema: landing; Owner: -
--

CREATE TABLE landing.complaints (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code character varying(20) NOT NULL,
    year integer NOT NULL,
    seq integer NOT NULL,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    consumername character varying(150) NOT NULL,
    consumeraddress character varying(250) NOT NULL,
    doctype character varying(5) NOT NULL,
    docnumber character varying(20) NOT NULL,
    phone character varying(20) NOT NULL,
    email character varying(150) NOT NULL,
    guardianname character varying(150),
    userid uuid,
    goodtype character varying(10) NOT NULL,
    claimedamount numeric(10,2),
    gooddescription character varying(500),
    complainttype character varying(10) NOT NULL,
    tripid uuid,
    tripcode character varying(60),
    reference character varying(200),
    detail text NOT NULL,
    request text NOT NULL,
    status character varying(12) DEFAULT 'pendiente'::character varying NOT NULL,
    duedate date NOT NULL,
    response text,
    respondedat timestamp without time zone,
    respondedby uuid,
    respondedbyname character varying(150),
    responseemailsent boolean DEFAULT false NOT NULL,
    confirmationemailsent boolean DEFAULT false NOT NULL,
    accesstoken character varying(64) NOT NULL,
    isbot boolean DEFAULT false NOT NULL,
    botreason character varying(200),
    closedreason character varying(500),
    closedat timestamp without time zone,
    closedby uuid,
    closedbyname character varying(150),
    responsedays integer DEFAULT 15 NOT NULL,
    CONSTRAINT complaints_claimedamount_check CHECK (((claimedamount IS NULL) OR (claimedamount >= (0)::numeric))),
    CONSTRAINT complaints_complainttype_check CHECK (((complainttype)::text = ANY ((ARRAY['reclamo'::character varying, 'queja'::character varying])::text[]))),
    CONSTRAINT complaints_doctype_check CHECK (((doctype)::text = ANY ((ARRAY['DNI'::character varying, 'CE'::character varying])::text[]))),
    CONSTRAINT complaints_goodtype_check CHECK (((goodtype)::text = ANY ((ARRAY['producto'::character varying, 'servicio'::character varying])::text[]))),
    CONSTRAINT complaints_status_check CHECK (((status)::text = ANY ((ARRAY['pendiente'::character varying, 'respondida'::character varying, 'descartada'::character varying, 'anulada'::character varying])::text[])))
);


--
-- Name: contactmessages; Type: TABLE; Schema: landing; Owner: -
--

CREATE TABLE landing.contactmessages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(120) NOT NULL,
    email character varying(200) NOT NULL,
    subject character varying(60) NOT NULL,
    message character varying(2000) NOT NULL,
    isread boolean DEFAULT false NOT NULL,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    readat timestamp without time zone,
    readbyuserid uuid,
    lastreplyat timestamp without time zone
);


--
-- Name: contactreplies; Type: TABLE; Schema: landing; Owner: -
--

CREATE TABLE landing.contactreplies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    contactid uuid NOT NULL,
    adminuserid uuid,
    adminname character varying(150),
    subject text NOT NULL,
    body text NOT NULL,
    status character varying(20) DEFAULT 'sent'::character varying NOT NULL,
    errormessage text,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    CONSTRAINT ck_contactreplies_status CHECK (((status)::text = ANY (ARRAY[('sent'::character varying)::text, ('failed'::character varying)::text])))
);


--
-- Name: faqitems; Type: TABLE; Schema: landing; Owner: -
--

CREATE TABLE landing.faqitems (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    lang character varying(5) DEFAULT 'es'::character varying NOT NULL,
    category character varying(60) NOT NULL,
    question character varying(300) NOT NULL,
    answer text NOT NULL,
    ispublished boolean DEFAULT true NOT NULL,
    sortorder integer DEFAULT 0 NOT NULL,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    updatedat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL
);


--
-- Name: holidays; Type: TABLE; Schema: landing; Owner: -
--

CREATE TABLE landing.holidays (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(100) NOT NULL,
    kind character varying(10) NOT NULL,
    month integer,
    day integer,
    movable character varying(20),
    date date,
    isactive boolean DEFAULT true NOT NULL,
    createdat timestamp without time zone DEFAULT (now() AT TIME ZONE 'utc'::text) NOT NULL,
    CONSTRAINT ck_holidays_kind CHECK (((((kind)::text = 'fijo'::text) AND (month IS NOT NULL) AND (day IS NOT NULL) AND (movable IS NULL) AND (date IS NULL)) OR (((kind)::text = 'movil'::text) AND (movable IS NOT NULL) AND (month IS NULL) AND (day IS NULL) AND (date IS NULL)) OR (((kind)::text = 'extra'::text) AND (date IS NOT NULL) AND (month IS NULL) AND (day IS NULL) AND (movable IS NULL)))),
    CONSTRAINT holidays_day_check CHECK (((day >= 1) AND (day <= 31))),
    CONSTRAINT holidays_kind_check CHECK (((kind)::text = ANY ((ARRAY['fijo'::character varying, 'movil'::character varying, 'extra'::character varying])::text[]))),
    CONSTRAINT holidays_month_check CHECK (((month >= 1) AND (month <= 12))),
    CONSTRAINT holidays_movable_check CHECK (((movable)::text = ANY ((ARRAY['jueves_santo'::character varying, 'viernes_santo'::character varying])::text[])))
);


