--
-- Name: promotions; Type: TABLE; Schema: rewards; Owner: -
--

CREATE TABLE rewards.promotions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name character varying(120) NOT NULL,
    description text,
